[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Global Internet Usage - Infographic Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    width: 1684px;
    height: 2384px;
    font-family: 'Inter', sans-serif;
    background: linear-gradient(175deg, #0a1628 0%, #0d1f3c 30%, #0a1a33 60%, #081426 100%);
    color: #ffffff;
    overflow: hidden;
    position: relative;
  }

  /* Subtle grid pattern overlay */
  body::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background-image:
      radial-gradient(circle at 20% 20%, rgba(0, 210, 255, 0.03) 0%, transparent 50%),
      radial-gradient(circle at 80% 60%, rgba(0, 150, 255, 0.03) 0%, transparent 50%),
      radial-gradient(circle at 50% 90%, rgba(0, 180, 255, 0.02) 0%, transparent 40%);
    pointer-events: none;
    z-index: 0;
  }

  /* Decorative network nodes */
  .network-dots {
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    pointer-events: none;
    z-index: 0;
    overflow: hidden;
  }
  .network-dots .dot {
    position: absolute;
    border-radius: 50%;
    background: rgba(0, 200, 255, 0.08);
  }
  .network-dots .line {
    position: absolute;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(0, 200, 255, 0.06), transparent);
    transform-origin: left center;
  }

  .poster {
    position: relative;
    z-index: 1;
    width: 100%;
    height: 100%;
    padding: 70px 80px 60px;
    display: flex;
    flex-direction: column;
  }

  /* ===== HEADER ===== */
  .header {
    text-align: center;
    margin-bottom: 40px;
    padding-bottom: 40px;
    border-bottom: 1px solid rgba(0, 200, 255, 0.15);
  }
  .header .subtitle-top {
    font-size: 18px;
    font-weight: 500;
    letter-spacing: 6px;
    text-transform: uppercase;
    color: rgba(0, 210, 255, 0.7);
    margin-bottom: 16px;
  }
  .header h1 {
    font-size: 56px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -1px;
    background: linear-gradient(135deg, #ffffff 0%, #b0e0ff 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    margin-bottom: 14px;
  }
  .header .tagline {
    font-size: 19px;
    font-weight: 300;
    color: rgba(255,255,255,0.55);
    max-width: 900px;
    margin: 0 auto;
    line-height: 1.5;
  }

  /* ===== HERO STAT ===== */
  .hero-stat {
    text-align: center;
    margin-bottom: 48px;
    padding: 50px 40px;
    background: linear-gradient(135deg, rgba(0, 180, 255, 0.08) 0%, rgba(0, 100, 200, 0.04) 100%);
    border: 1px solid rgba(0, 200, 255, 0.12);
    border-radius: 24px;
    position: relative;
    overflow: hidden;
  }
  .hero-stat::before {
    content: '';
    position: absolute;
    top: -2px; left: 20%; right: 20%;
    height: 3px;
    background: linear-gradient(90deg, transparent, #00d4ff, transparent);
    border-radius: 2px;
  }
  .hero-stat .big-number {
    font-size: 120px;
    font-weight: 900;
    letter-spacing: -3px;
    line-height: 1;
    background: linear-gradient(135deg, #00d4ff 0%, #00a0ff 40%, #7c5cff 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    margin-bottom: 8px;
  }
  .hero-stat .big-unit {
    font-size: 52px;
    font-weight: 700;
    letter-spacing: -1px;
  }
  .hero-stat .big-label {
    font-size: 26px;
    font-weight: 500;
    color: rgba(255,255,255,0.7);
    margin-top: 8px;
  }
  .hero-stat .big-sublabel {
    font-size: 17px;
    font-weight: 300;
    color: rgba(255,255,255,0.4);
    margin-top: 6px;
  }

  /* ===== MINI STAT STRIP ===== */
  .stat-strip {
    display: flex;
    justify-content: center;
    gap: 50px;
    margin-bottom: 48px;
  }
  .stat-strip .mini-stat {
    text-align: center;
    padding: 20px 30px;
    background: rgba(0, 180, 255, 0.05);
    border: 1px solid rgba(0, 200, 255, 0.1);
    border-radius: 16px;
    min-width: 200px;
  }
  .stat-strip .mini-stat .mini-val {
    font-size: 38px;
    font-weight: 800;
    color: #00d4ff;
    line-height: 1.1;
  }
  .stat-strip .mini-stat .mini-label {
    font-size: 13px;
    font-weight: 500;
    color: rgba(255,255,255,0.5);
    margin-top: 6px;
    text-transform: uppercase;
    letter-spacing: 1.5px;
  }

  /* ===== SECTION HEADER ===== */
  .section-header {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 28px;
  }
  .section-header .section-num {
    width: 38px;
    height: 38px;
    background: linear-gradient(135deg, #00d4ff, #0088cc);
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
    font-weight: 700;
    flex-shrink: 0;
  }
  .section-header h2 {
    font-size: 28px;
    font-weight: 700;
    color: #ffffff;
    letter-spacing: -0.5px;
  }

  /* ===== PENETRATION CHART (Custom Horizontal Bar) ===== */
  .pen-section {
    margin-bottom: 48px;
  }
  .pen-chart {
    display: flex;
    flex-direction: column;
    gap: 14px;
  }
  .pen-row {
    display: flex;
    align-items: center;
    gap: 16px;
  }
  .pen-row .pen-country {
    width: 140px;
    text-align: right;
    font-size: 15px;
    font-weight: 500;
    color: rgba(255,255,255,0.8);
    flex-shrink: 0;
  }
  .pen-row .pen-bar-bg {
    flex: 1;
    height: 32px;
    background: rgba(255,255,255,0.04);
    border-radius: 6px;
    position: relative;
    overflow: hidden;
  }
  .pen-row .pen-bar-fill {
    height: 100%;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding-right: 12px;
    font-size: 14px;
    font-weight: 700;
    color: #fff;
    min-width: 50px;
    transition: width 0.5s ease;
  }
  .pen-row .pen-pop {
    width: 130px;
    text-align: right;
    font-size: 13px;
    font-weight: 400;
    color: rgba(255,255,255,0.45);
    flex-shrink: 0;
  }

  /* ===== CHINA & INDIA CALLOUT ===== */
  .callout-row {
    display: flex;
    gap: 30px;
    margin-bottom: 48px;
  }
  .callout-card {
    flex: 1;
    padding: 36px 32px;
    border-radius: 20px;
    position: relative;
    overflow: hidden;
  }
  .callout-card.china {
    background: linear-gradient(135deg, rgba(255, 59, 48, 0.12) 0%, rgba(255, 100, 50, 0.06) 100%);
    border: 1px solid rgba(255, 80, 50, 0.2);
  }
  .callout-card.india {
    background: linear-gradient(135deg, rgba(255, 160, 0, 0.12) 0%, rgba(255, 200, 50, 0.06) 100%);
    border: 1px solid rgba(255, 180, 50, 0.2);
  }
  .callout-card .callout-flag {
    font-size: 42px;
    margin-bottom: 12px;
  }
  .callout-card .callout-country {
    font-size: 20px;
    font-weight: 600;
    margin-bottom: 8px;
    color: rgba(255,255,255,0.9);
  }
  .callout-card .callout-num {
    font-size: 52px;
    font-weight: 900;
    line-height: 1;
    margin-bottom: 6px;
  }
  .callout-card.china .callout-num { color: #ff6b4a; }
  .callout-card.india .callout-num { color: #ffb830; }
  .callout-card .callout-desc {
    font-size: 14px;
    font-weight: 400;
    color: rgba(255,255,255,0.5);
    line-height: 1.5;
  }
  .callout-card .callout-pen {
    margin-top: 14px;
    display: inline-block;
    padding: 6px 14px;
    border-radius: 20px;
    font-size: 13px;
    font-weight: 600;
  }
  .callout-card.china .callout-pen { background: rgba(255, 80, 50, 0.15); color: #ff8a70; }
  .callout-card.india .callout-pen { background: rgba(255, 180, 50, 0.15); color: #ffd060; }

  /* ===== SOCIAL MEDIA + ECONOMY ROW ===== */
  .bottom-row {
    display: flex;
    gap: 30px;
    flex: 1;
  }

  /* Social media section */
  .social-section {
    flex: 1;
    display: flex;
    flex-direction: column;
  }
  .social-platforms {
    display: flex;
    flex-direction: column;
    gap: 12px;
    flex: 1;
  }
  .social-row {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 14px 18px;
    background: rgba(255,255,255,0.03);
    border-radius: 12px;
    border: 1px solid rgba(255,255,255,0.05);
  }
  .social-row .social-icon {
    width: 40px;
    height: 40px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    font-weight: 700;
    flex-shrink: 0;
    color: #fff;
  }
  .social-row .social-name {
    flex: 1;
    font-size: 16px;
    font-weight: 600;
    color: rgba(255,255,255,0.85);
  }
  .social-row .social-users {
    font-size: 20px;
    font-weight: 800;
    color: #00d4ff;
  }
  .social-row .social-unit {
    font-size: 12px;
    font-weight: 500;
    color: rgba(255,255,255,0.4);
    margin-left: 4px;
  }
  .social-avg {
    margin-top: 16px;
    padding: 16px 20px;
    background: rgba(0, 180, 255, 0.06);
    border: 1px solid rgba(0, 200, 255, 0.1);
    border-radius: 12px;
    text-align: center;
  }
  .social-avg .avg-val {
    font-size: 36px;
    font-weight: 800;
    color: #00d4ff;
  }
  .social-avg .avg-label {
    font-size: 12px;
    font-weight: 500;
    color: rgba(255,255,255,0.5);
    text-transform: uppercase;
    letter-spacing: 1.5px;
    margin-top: 4px;
  }

  /* Economy section */
  .economy-section {
    flex: 1;
    display: flex;
    flex-direction: column;
  }
  .economy-cards {
    display: flex;
    flex-direction: column;
    gap: 18px;
    flex: 1;
  }
  .econ-card {
    padding: 28px 24px;
    border-radius: 16px;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.06);
  }
  .econ-card.highlight {
    background: linear-gradient(135deg, rgba(0, 210, 255, 0.1) 0%, rgba(100, 50, 255, 0.06) 100%);
    border: 1px solid rgba(0, 200, 255, 0.2);
    position: relative;
  }
  .econ-card.highlight::before {
    content: '';
    position: absolute;
    top: -1px; left: 15%; right: 15%;
    height: 2px;
    background: linear-gradient(90deg, transparent, #00d4ff, transparent);
  }
  .econ-card .econ-label {
    font-size: 13px;
    font-weight: 500;
    color: rgba(255,255,255,0.45);
    text-transform: uppercase;
    letter-spacing: 1.5px;
    margin-bottom: 8px;
  }
  .econ-card .econ-val {
    font-size: 48px;
    font-weight: 900;
    line-height: 1;
  }
  .econ-card.highlight .econ-val {
    background: linear-gradient(135deg, #00d4ff, #7c5cff);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }
  .econ-card .econ-val.green { color: #34d399; }
  .econ-card .econ-val.purple { color: #a78bfa; }
  .econ-card .econ-val.teal { color: #2dd4bf; }
  .econ-card .econ-desc {
    font-size: 14px;
    font-weight: 400;
    color: rgba(255,255,255,0.45);
    margin-top: 8px;
    line-height: 1.5;
  }

  /* ===== FOOTER ===== */
  .footer {
    margin-top: 36px;
    padding-top: 24px;
    border-top: 1px solid rgba(0, 200, 255, 0.1);
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .footer .footer-left {
    font-size: 12px;
    color: rgba(255,255,255,0.3);
    line-height: 1.6;
  }
  .footer .footer-right {
    font-size: 12px;
    color: rgba(255,255,255,0.25);
    text-align: right;
  }

  /* Bar colors */
  .bar-sk { background: linear-gradient(90deg, #00d4ff, #00a0e0); }
  .bar-uk { background: linear-gradient(90deg, #00c4e8, #0098d0); }
  .bar-de { background: linear-gradient(90deg, #00b8d8, #0090c0); }
  .bar-us { background: linear-gradient(90deg, #00acd0, #0088b8); }
  .bar-jp { background: linear-gradient(90deg, #00a0c8, #0080b0); }
  .bar-br { background: linear-gradient(90deg, #0094b8, #0078a0); }
  .bar-id { background: linear-gradient(90deg, #0088a8, #007098); }
  .bar-cn { background: linear-gradient(90deg, #007c98, #006888); }
  .bar-in { background: linear-gradient(90deg, #007088, #005c78); }
  .bar-ng { background: linear-gradient(90deg, #006478, #005068); }
</style>
</head>
