const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--font-render-hinting=none']
  });

  const page = await browser.newPage();

  // A1 portrait at 72 DPI: 1684 x 2384 px
  await page.setViewport({ width: 1684, height: 2384, deviceScaleFactor: 2 });

  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for fonts
  await page.evaluate(() => document.fonts.ready);
  await new Promise(r => setTimeout(r, 1000));

  await page.screenshot({
    path: '/app/output/final_poster.png',
    type: 'png',
    clip: { x: 0, y: 0, width: 1684, height: 2384 },
    omitBackground: false
  });

  console.log('Screenshot saved to /app/output/final_poster.png');

  await browser.close();
})();

